const profile = $('Check Graph Profile').first().json ?? {};
const chats = $('Check Teams Chats').first().json ?? {};
const abos = $('Abos abrufen').first().json ?? {};
const abo = $('Agent-Abo waehlen').first().json?.abo ?? {};
const verlaengerung = $('Abo verlaengern').isExecuted ? ($('Abo verlaengern').first().json ?? {}) : null;
const cfg = $('Config').first().json ?? {};

const statusOf = (r) => Number(
  r?.statusCode ??
  r?.status ??
  r?.response?.statusCode ??
  r?.response?.status ??
  r?.error?.statusCode ??
  r?.error?.httpCode ??
  0
);

const bodyOf = (r) => {
  if (r?.body && typeof r.body === 'object') return r.body;
  if (r?.data && typeof r.data === 'object') return r.data;
  if (r?.response?.body && typeof r.response.body === 'object') return r.response.body;
  return r;
};

const errorOf = (r) => {
  const b = bodyOf(r);
  const candidates = [
    b?.error?.message,
    r?.error?.message,
    r?.message,
    r?.errorMessage,
    ...(Array.isArray(r?.errorDetails?.rawErrorMessage) ? r.errorDetails.rawErrorMessage : []),
    r?.errorDetails?.rawErrorMessage,
    r?.cause?.message,
  ];
  return candidates
    .filter(v => v !== undefined && v !== null && String(v).trim())
    .map(v => String(v).trim())
    .join(' | ');
};

const ok = (s) => s >= 200 && s < 300;

const profileStatus = statusOf(profile);
const chatsStatus = statusOf(chats);
const abosStatus = statusOf(abos);
const profileBody = bodyOf(profile);
const chatsBody = bodyOf(chats);

const profileHealthy = ok(profileStatus) && Boolean(profileBody?.id);
const chatsHealthy = ok(chatsStatus) && Array.isArray(chatsBody?.value);

// Das Graph-Abo des Teams-Agenten. n8n legt es nur beim Aktivieren an und
// verlaengert es nie; nach 72 Stunden empfaengt der Agent nichts mehr, ohne
// dass irgendwo ein Fehler entsteht. Neu anlegen kann es nur der Trigger
// selbst, weil nur er das clientState-Geheimnis kennt.
const abosLesbar = ok(abosStatus) && Array.isArray(bodyOf(abos)?.value);
const aboGefunden = Boolean(abo.id);
const verlaengerungStatus = verlaengerung ? statusOf(verlaengerung) : 0;
const verlaengert = Boolean(verlaengerung) && ok(verlaengerungStatus);
const aboAblauf = String(
  (verlaengert ? bodyOf(verlaengerung)?.expirationDateTime : '') ||
  abo.expirationDateTime ||
  ''
);
const aboHealthy = abosLesbar && aboGefunden && (!verlaengerung || verlaengert);

const account = String(
  profileBody?.mail ??
  profileBody?.userPrincipalName ??
  ''
).trim().toLowerCase();

const expectedAccount = String(cfg.expectedAccount ?? '')
  .trim()
  .toLowerCase();

const accountHealthy = !expectedAccount || account === expectedAccount;

const reasons = [];

if (!profileHealthy) {
  reasons.push(
    profileStatus
      ? `Graph-Profil fehlgeschlagen: HTTP ${profileStatus}${errorOf(profile) ? ` – ${errorOf(profile)}` : ''}`
      : `Graph-Profil: Transportfehler ohne HTTP-Antwort${errorOf(profile) ? ` – ${errorOf(profile)}` : ''}`
  );
}

if (!chatsHealthy) {
  reasons.push(
    chatsStatus
      ? `Teams-Chat-Zugriff fehlgeschlagen: HTTP ${chatsStatus}${errorOf(chats) ? ` – ${errorOf(chats)}` : ''}`
      : `Teams-Chat-Zugriff: Transportfehler ohne HTTP-Antwort${errorOf(chats) ? ` – ${errorOf(chats)}` : ''}`
  );
}

if (!abosLesbar) {
  reasons.push(
    abosStatus
      ? `Abo-Liste nicht lesbar: HTTP ${abosStatus}${errorOf(abos) ? ` – ${errorOf(abos)}` : ''}`
      : `Abo-Liste: Transportfehler ohne HTTP-Antwort${errorOf(abos) ? ` – ${errorOf(abos)}` : ''}`
  );
} else if (!aboGefunden) {
  reasons.push('Kein Graph-Abo für den Teams-Agenten – er empfängt keine Nachrichten. Abhilfe: RWG Teams Agent neu publizieren');
}

if (verlaengerung && !verlaengert) {
  reasons.push(
    `Abo-Verlängerung fehlgeschlagen: HTTP ${verlaengerungStatus || 'ohne Antwort'}${errorOf(verlaengerung) ? ` – ${errorOf(verlaengerung)}` : ''} – läuft ab ${abo.expirationDateTime}`
  );
}

if (!accountHealthy) {
  reasons.push(
    `Unerwartetes Microsoft-Konto: ${account || '[unbekannt]'} statt ${expectedAccount}`
  );
}

return [{
  json: {
    healthcheckName: cfg.healthcheckName,
    healthy: profileHealthy && chatsHealthy && aboHealthy && accountHealthy,
    checkedAt: new Date().toISOString(),
    account,
    displayName: String(profileBody?.displayName ?? ''),
    profileStatus,
    chatsStatus,
    abosStatus,
    visibleChatCount: Array.isArray(chatsBody?.value) ? chatsBody.value.length : 0,
    aboId: String(abo.id ?? ''),
    aboAblauf,
    aboVerlaengert: verlaengert,
    profileError: errorOf(profile),
    chatsError: errorOf(chats),
    reasons,
    errorMessage: reasons.join(' | '),
  },
}];

// Der Grund steht direkt unter der Kopfzeile: Der Fehlermelder kuerzt die
// Meldung auf 300 Zeichen, und die Messwerte darunter sind entbehrlicher.
const r = $input.first().json ?? {};
return [{json:{...r,failureMessage:[
  `Healthcheck fehlgeschlagen: ${r.healthcheckName || 'Microsoft Graph & Teams'}`,
  `Grund: ${r.errorMessage || 'Unbekannter Fehler'}`,
  `Zeitpunkt: ${r.checkedAt || new Date().toISOString()}`,
  `Konto: ${r.account || '[unbekannt]'}`,
  `Graph /me: HTTP ${r.profileStatus || 'unbekannt'}`,
  `Graph /me/chats: HTTP ${r.chatsStatus || 'unbekannt'}`,
  `Agent-Abo: ${r.aboId ? `läuft ab ${r.aboAblauf}` : 'nicht gefunden'}`
].join('\n')}}];
